var uniqueXorTriplets = function(nums) {
    const n = nums.length;
    const set = new Set();

    for (let j = 0; j < n; j++) {
        for (let k = j; k < n; k++) {
            set.add(nums[j] ^ nums[k]);
        }
    }

    const overallSet = new Set();

    for (let i = 0; i < n; i++) {
        for (const val of set) {
            overallSet.add(nums[i] ^ val);
        }
    }

    return overallSet.size;
};

