var uniqueXorTriplets = function(nums) {
    const n = nums.length;
    const pairSet = new Set();

    for (let j = 0; j < n; j++) {
        for (let k = j + 1; k < n; k++) {
            pairSet.add(nums[j] ^ nums[k]);
        }
    }

    const seen = new Set();

    for (const num of nums) {
        for (const pair of pairSet) {
            seen.add(num ^ pair);
        }
    }

    return seen.size;
};

